function restore(s){blocks=s.blocks;name=s.name;description=s.description;templateId=s.templateId;blockSize=s.blockSize;selection=new Set(s.selection||[]);layer=Infinity;rebuild();}
function history(direction){const from=direction==='undo'?undo:redo,to=direction==='undo'?redo:undo;if(!from.length)return;to.push(snapshot());restore(from.pop());dirty=true;}
$('undo-btn').onclick=()=>history('undo');$('redo-btn').onclick=()=>history('redo');$('fit-btn').onclick=()=>fit();$('zoom-in').onclick=()=>{camera.zoom=Math.min(4,camera.zoom*1.2);camera.updateProjectionMatrix();};$('zoom-out').onclick=()=>{camera.zoom=Math.max(.3,camera.zoom/1.2);camera.updateProjectionMatrix();};
$('layer-range').oninput=e=>{const value=Number(e.target.value);layer=value===Number(e.target.max)?Infinity:value;group.children.forEach(m=>m.visible=m.userData.block.y<=layer);ghost.visible=false;updateUI();};$('all-layers').onclick=()=>{layer=Infinity;group.children.forEach(m=>m.visible=true);updateUI();};
$('block-size').onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<.1||value>10){e.target.value=blockSize;toast('Bitte eine Blockgröße zwischen 0,1 und 10 cm eingeben.');return;}remember();blockSize=value;updateUI();};
$('confirm-cancel').onclick=()=>$('confirm-dialog').close();$('new-btn').onclick=()=>requestReplace(()=>{remember();selection.clear();blocks=[];name='Meine Blockblume';description='Dein freier Entwurf beginnt mit dem ersten Block.';templateId=null;layer=Infinity;rebuild();fit();toast('Klicke auf das Bodenraster, um loszubauen.');},'Ohne Vorlage starten?');
$('help-btn').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();
window.addEventListener('keydown',e=>{if(editingTarget(e.target)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();history(e.shiftKey?'redo':'undo');}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();history('redo');}else if(tool==='select'&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();$('select-all').click();}else if(tool==='select'&&e.key==='Escape'){selection.clear();updateSelection();}else if(tool==='select'&&selection.size&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','PageUp','PageDown'].includes(e.key)){e.preventDefault();const [axis,direction]={ArrowLeft:['x',-1],ArrowRight:['x',1],ArrowUp:['y',1],ArrowDown:['y',-1],PageUp:['z',-1],PageDown:['z',1]}[e.key];moveBy(axis,direction);}else if(!e.ctrlKey&&!e.metaKey){const next={b:'add',f:'paint',e:'remove',s:'select',v:'orbit'}[e.key.toLowerCase()];if(next)setTool(next);}});
rebuild();renderTemplates();setColor('red');setTool('add');fit();
renderer.setAnimationLoop(()=>{if(!down?.area)controls.update();renderer.render(scene,camera);});
function editingTarget(target){return target instanceof Element&&(target.isContentEditable||Boolean(target.closest('textarea,select,input:not([type="checkbox"]):not([type="radio"])')));}
window.addEventListener('keydown',e=>{if(editingTarget(e.target)||document.querySelector('dialog[open]')||tool!=='select'||!selection.size)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();try{duplicateSelection();}catch(error){actionError(error);}}else if(!e.ctrlKey&&!e.metaKey&&['Delete','Backspace'].includes(e.key)){e.preventDefault();try{deleteSelection();}catch(error){actionError(error);}}});
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const filename=()=>name.toLowerCase().replace(/[^a-z0-9äöüß]+/g,'-');
$('save-btn').onclick=()=>{download(`${filename()}.blockart.json`,JSON.stringify({format:'blockart',version:1,name,description,blockSize,blocks},null,2),'application/json');dirty=false;toast('Projektdatei gespeichert. Du kannst sie später wieder öffnen.');};
$('import-btn').onclick=()=>$('import-file').click();
$('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>150000)throw new Error('Diese Datei ist zu groß für ein BlockArt-Projekt.');const data=JSON.parse(await file.text());if(data.format!=='blockart'||data.version!==1||typeof data.name!=='string'||data.name.length>100||typeof data.description!=='string'||data.description.length>300||!Number.isFinite(data.blockSize)||data.blockSize<.1||data.blockSize>10)throw new Error('Bitte eine gültige BlockArt-Projektdatei öffnen.');const next=validateBlocks(data.blocks);requestReplace(()=>{remember();selection.clear();blocks=next;name=data.name;description=data.description;blockSize=data.blockSize;templateId=null;layer=Infinity;rebuild();fit();dirty=false;toast('Projekt geöffnet.');},'Gespeichertes Projekt öffnen?');}catch(error){toast(error.message||'Die Datei konnte nicht geöffnet werden.');}};
function showPlan(){
  const root=$('plan-content');root.replaceChildren();const d=dimensions(blocks,blockSize),summary=document.createElement('div');summary.className='plan-summary';summary.textContent=`${name} · ${blocks.length} / 120 Blöcke · ${d.x.toLocaleString('de-DE')} × ${d.y.toLocaleString('de-DE')} × ${d.z.toLocaleString('de-DE')} cm (B × H × T)`;root.append(summary);
  if(!blocks.length){const empty=document.createElement('p');empty.className='plan-note';empty.textContent='Dein Bauplan ist noch leer. Setze den ersten Block auf das Raster.';root.append(empty);$('csv-btn').disabled=true;$('plan-dialog').showModal();return;}$('csv-btn').disabled=false;
  const count=components(blocks),note=document.createElement('p');note.className='plan-note';note.textContent=count>1?`Dein Modell enthält ${count} getrennte Teile. Verbinde sie für den Aufbau. Überhänge brauchen Halt; Standfestigkeit wird nicht berechnet.`:'Alle Blöcke sind über ihre Flächen verbunden. Überhänge brauchen Halt, z. B. durch Kleben. Standfestigkeit wird nicht berechnet.';root.append(note);
  const table=document.createElement('table');table.className='color-table';table.innerHTML='<thead><tr><th scope="col">Farbe</th><th scope="col">Anzahl</th></tr></thead>';const tbody=document.createElement('tbody');for(const c of PALETTE){const n=blocks.filter(b=>b.color===c.id).length;if(!n)continue;const row=document.createElement('tr'),label=document.createElement('td'),amount=document.createElement('td'),chip=document.createElement('span');chip.className='color-chip';chip.style.background=c.hex;label.append(chip,document.createTextNode(c.name));amount.textContent=n;row.append(label,amount);tbody.append(row);}table.append(tbody);root.append(table);
  const title=document.createElement('h3');title.textContent='Schicht für Schicht · von unten nach oben';title.style.margin='24px 0 12px';root.append(title);const axes=document.createElement('p');axes.className='plan-axes';axes.textContent=`Draufsicht: links → rechts = X, oben → unten = Z (hinten → vorne). Kantenlänge: ${blockSize.toLocaleString('de-DE')} cm. Leere Felder bleiben frei.`;root.append(axes);
  const minX=Math.min(...blocks.map(b=>b.x)),maxX=Math.max(...blocks.map(b=>b.x)),minZ=Math.min(...blocks.map(b=>b.z)),maxZ=Math.max(...blocks.map(b=>b.z));const width=maxX-minX+1,depth=maxZ-minZ+1,size=Math.max(width,depth);const layers=document.createElement('div');layers.className='layer-plans';
  for(let y=0;y<=Math.max(...blocks.map(b=>b.y));y++){const layerBlocks=blocks.filter(b=>b.y===y),section=document.createElement('section');section.className='layer-plan';const heading=document.createElement('h3');heading.textContent=`Schicht ${y+1} · ${layerBlocks.length} ${layerBlocks.length===1?'Block':'Blöcke'}`;section.append(heading);const grid=document.createElement('div');grid.className='layer-grid';grid.style.gridTemplateColumns=`repeat(${size},1fr)`;const map=new Map(layerBlocks.map(b=>[`${b.x},${b.z}`,b]));for(let z=0;z<size;z++)for(let x=0;x<size;x++){const cell=document.createElement('div');cell.className='layer-cell';const block=map.get(`${minX+x},${minZ+z}`);if(block){cell.style.background=colorOf(block.color);cell.title=`X ${block.x}, Y ${y}, Z ${block.z}: ${PALETTE.find(c=>c.id===block.color).name}`;}grid.append(cell);}section.append(grid);layers.append(section);}root.append(layers);$('plan-dialog').showModal();
}
$('show-plan-btn').onclick=showPlan;$('plan-tab').onclick=showPlan;$('studio-tab').onclick=()=>{$('plan-dialog').close();host.scrollIntoView({behavior:'smooth',block:'center'});};$('close-plan').onclick=()=>$('plan-dialog').close();$('print-btn').onclick=()=>window.print();
$('csv-btn').onclick=()=>{const rows=[['Schicht','X','Y','Z','Farbe','Kantenlänge (cm)'],...blocks.toSorted((a,b)=>a.y-b.y||a.z-b.z||a.x-b.x).map(b=>[b.y+1,b.x,b.y,b.z,PALETTE.find(c=>c.id===b.color).name,blockSize.toLocaleString('de-DE')])];download(`${filename()}-bauplan.csv`,'\uFEFF'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Blockliste heruntergeladen.');};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
const context=document.modelContext;
if(context?.registerTool){
  const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  const state=()=>({name,blocks:structuredClone(blocks),selectedPositions:[...selection].map(key=>{const [x,y,z]=key.split(',').map(Number);return {x,y,z};}),blockSize,used:blocks.length,remaining:MAX_BLOCKS-blocks.length,dimensionsCm:dimensions(blocks,blockSize)});
  const definitions=[
    {name:'select_screen_rectangle',description:'Select all cube centers in a rectangle of the current canvas, including occluded cubes on the shown layers. Coordinates are CSS pixels relative to the canvas.',inputSchema:{type:'object',properties:{left:{type:'number',minimum:0},right:{type:'number',minimum:0},top:{type:'number',minimum:0},bottom:{type:'number',minimum:0},additive:{type:'boolean'}},required:['left','right','top','bottom'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(input?.additive!==undefined&&typeof input.additive!=='boolean')throw new Error('Invalid additive option.');setTool('select');selectArea(input,Boolean(input.additive));return state();}},
    {name:'duplicate_selected_blocks',description:'Duplicate the whole selection into a free neighboring position within the 120-block budget. Selects the copy. Can be undone.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{duplicateSelection();return state();}},
    {name:'delete_selected_blocks',description:'Delete the whole selected group and return its blocks to the inventory. Can be undone.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{deleteSelection();return state();}},
    {name:'select_model_blocks',description:'Select existing cubes by their exact grid positions, replacing the prior selection without changing the model.',inputSchema:{type:'object',properties:{positions:{type:'array',maxItems:120,items:{type:'object',properties:{x:{type:'integer'},y:{type:'integer'},z:{type:'integer'}},required:['x','y','z'],additionalProperties:false}}},required:['positions'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!Array.isArray(input?.positions)||input.positions.length>120||input.positions.some(b=>!b||!['x','y','z'].every(k=>Number.isInteger(b[k]))))throw new Error('Invalid positions.');const next=new Set(input.positions.map(keyOf)),present=new Set(blocks.map(keyOf));if([...next].some(key=>!present.has(key)))throw new Error('Select only existing blocks.');selection=next;setTool('select');updateSelection();return state();}},
    {name:'move_selected_blocks',description:'Move all selected cubes together by integer X/Y/Z offsets. Collisions and grid boundaries reject the entire move. One undo step.',inputSchema:{type:'object',properties:{x:{type:'integer',minimum:-30,maximum:30},y:{type:'integer',minimum:-30,maximum:30},z:{type:'integer',minimum:-30,maximum:30}},required:['x','y','z'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{moveSelection(input);return state();}},
    {name:'read_block_model',description:'Read the current flower model, block coordinates, remaining inventory and dimensions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>state()},
    {name:'load_flower_template',description:'Replace the current model with a flower template; the replacement can be undone.',inputSchema:{type:'object',properties:{templateId:{type:'string',enum:TEMPLATES.map(t=>t.id)}},required:['templateId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{const t=TEMPLATES.find(t=>t.id===input?.templateId);if(!t)throw new Error('Unknown template.');loadTemplate(t);category=t.category;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));renderTemplates();return state();}},
    {name:'add_model_blocks',description:'Add colored cubes to empty grid positions, respecting the inventory of 120 blocks. The whole batch is one undo step.',inputSchema:{type:'object',properties:{blocks:{type:'array',maxItems:120,items:{type:'object',properties:{x:{type:'integer',minimum:-15,maximum:15},y:{type:'integer',minimum:0,maximum:30},z:{type:'integer',minimum:-15,maximum:15},color:{type:'string',enum:PALETTE.map(c=>c.id)}},required:['x','y','z','color'],additionalProperties:false}}},required:['blocks'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!Array.isArray(input?.blocks)||!input.blocks.length)throw new Error('Supply at least one block.');const merged=validateBlocks([...blocks,...input.blocks]);remember();blocks=merged;templateId=null;layer=Infinity;rebuild();return state();}}
  ];for(const definition of definitions){try{Promise.resolve(context.registerTool(definition,{signal:lifecycle.signal})).catch(error=>console.warn('WebMCP registration failed',error));}catch(error){console.warn('WebMCP registration failed',error);}}
}



